import { SITE_URL } from "@/lib/profile";

/**
 * Hand-written rather than generated by app/robots.ts, because MetadataRoute.Robots can
 * only emit the directives it knows about and there is no field for `Content-Signal`.
 *
 * Content signals are set to yes across the board on purpose. The point of this site is
 * to be found and quoted: search=yes for indexing, ai-input=yes so assistants may use the
 * page to ground an answer, ai-train=yes so models learn the name without needing a live
 * fetch. Flip ai-train to no only if the tradeoff changes.
 *
 * Note: Cloudflare's "Managed robots.txt" writes its own file at the edge with
 * ai-train=no, which would override this. Keep that toggle off.
 */
const BODY = `# ${SITE_URL}
# Content-Signal declarations follow contentsignals.org. Terms:
#   search=yes    building a search index and linking back is allowed
#   ai-input=yes  using this page to ground an AI answer is allowed
#   ai-train=yes  using this page to train or fine-tune a model is allowed

User-agent: *
Content-Signal: search=yes, ai-input=yes, ai-train=yes
Allow: /
Disallow: /cms
Disallow: /cms/
Disallow: /api/auth
Disallow: /api/callback

# Machine-readable representations of this site
# Markdown profile:  ${SITE_URL}/index.md   (also GET / with Accept: text/markdown)
# Answer corpus:     ${SITE_URL}/answers.json
# Summary:           ${SITE_URL}/llms.txt
# Full context:      ${SITE_URL}/llms-full.txt
# API catalog:       ${SITE_URL}/.well-known/api-catalog

Sitemap: ${SITE_URL}/sitemap.xml
Host: ${SITE_URL}
`;

export function GET() {
  return new Response(BODY, {
    headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "public, max-age=3600, s-maxage=86400" },
  });
}
